const base = data.directory;
const readme = "# " + base.split("/").at(-1) + "\n\n" + data.introduction + "\n";
const receipts = await Promise.all([
  write(base + "/LICENSE", data.license),
  write(base + "/README.md", readme),
]);
const saved = await Promise.all([
  read({path:base + "/LICENSE", complete:true}),
  read({path:base + "/README.md", complete:true}),
]);
if (saved[0] !== data.license || saved[1] !== readme) throw Error("scaffold content changed");
return {directory:base, receipts};
